"""Time Machine & Record Label Crate Digging Engine for Album Discovery.
Provides curated landmark studio album discographies by historical release year
and legendary record label catalogs with unlimited real-time deep crate digging.
"""
import json
import os
import urllib.parse
from ..utils.http_client import fetch_json

_DATA_PATH = os.path.join(os.path.dirname(os.path.dirname(__file__)), "data", "timemachine_landmarks.json")

def _load_landmarks() -> dict:
    try:
        if os.path.exists(_DATA_PATH):
            with open(_DATA_PATH, "r", encoding="utf-8") as f:
                raw = json.load(f)
                return {int(k): v for k, v in raw.items()}
    except Exception:
        pass
    return {}

