def _fetch_live_year_albums(year: int, limit: int = 40, offset: int = 0) -> list[dict]:
    """Fetch additional historical albums from Deezer by year."""
    try:
        url = f"https://api.deezer.com/search/album?q=year:{year}&limit={limit}&index={offset}"
        data = fetch_json(url, cache_ttl=7200)
        items = data.get("data", []) if data else []
        results = []
        for it in items:
            aid = str(it.get("id") or "")
            title = (it.get("title") or "").strip()
            artist_obj = it.get("artist") or {}
            artist = (artist_obj.get("name") or "Various Artists").strip()
            cov = it.get("cover_xl") or it.get("cover_big") or it.get("cover_medium") or ""
            if not aid or not title:
                continue
            results.append({
                "id": aid,
                "title": title,
                "artist": artist,
                "year": str(it.get("release_date") or year)[:4],
                "genre": f"{year} Archive",
                "cover": cov,
                "tracks_count": it.get("nb_tracks") or 10,
                "desc": f"Official {year} studio release."
            })
        return results
    except Exception:
        return []


def _fetch_live_label_albums(label_name: str, limit: int = 40, offset: int = 0) -> list[dict]:
    """Fetch deep independent catalog albums from Deezer by label."""
    try:
        q = urllib.parse.quote(f'label:"{label_name}"')
        url = f"https://api.deezer.com/search/album?q={q}&limit={limit}&index={offset}"
        data = fetch_json(url, cache_ttl=7200)
        items = data.get("data", []) if data else []
        results = []
        for it in items:
            aid = str(it.get("id") or "")
            title = (it.get("title") or "").strip()
            artist_obj = it.get("artist") or {}
            artist = (artist_obj.get("name") or "Various Artists").strip()
            cov = it.get("cover_xl") or it.get("cover_big") or it.get("cover_medium") or ""
            if not aid or not title:
                continue
            results.append({
                "id": aid,
                "title": title,
                "artist": artist,
                "year": str(it.get("release_date") or "")[:4] or "----",
                "genre": label_name,
                "cover": cov,
                "tracks_count": it.get("nb_tracks") or 10,
                "desc": f"Official {label_name} recording.",
                "label": label_name
            })
        return results
    except Exception:
        return []


def get_timemachine_years() -> list[int]:
    """Return available landmark years in chronological order (1960-2026)."""
    if TIMEMACHINE_LANDMARKS:
        return sorted(TIMEMACHINE_LANDMARKS.keys())
    return list(range(1960, 2027))


def get_timemachine_albums(year: int, limit: int = 40, offset: int = 0) -> dict:
    """Return landmark albums for a specific historical year with unlimited crate digging."""
    try:
        y = int(year)
    except (ValueError, TypeError):
        y = 1994
    if y not in TIMEMACHINE_LANDMARKS and (y < 1950 or y > 2030):
        y = 1994
    curated = TIMEMACHINE_LANDMARKS.get(y, [])

    if offset == 0:
        seen_ids = {str(a["id"]) for a in curated}
        live_needed = max(0, limit - len(curated))
        live_albums = _fetch_live_year_albums(y, limit=max(25, live_needed), offset=0)
        merged = list(curated)
        for la in live_albums:
            if str(la["id"]) not in seen_ids:
                seen_ids.add(str(la["id"]))
                merged.append(la)
        return {
            "year": y,
            "available_years": get_timemachine_years(),
            "albums": merged,
            "total": len(merged),
            "offset": 0,
            "has_more": True
        }
    else:
        live_albums = _fetch_live_year_albums(y, limit=limit, offset=offset)
        curated_ids = {str(a["id"]) for a in curated}
        clean_live = [a for a in live_albums if str(a["id"]) not in curated_ids]
        return {
            "year": y,
            "available_years": get_timemachine_years(),
            "albums": clean_live,
            "total": len(clean_live),
            "offset": offset,
            "has_more": len(live_albums) >= limit
        }


def get_label_catalogs(label_key: str = "", limit: int = 40, offset: int = 0) -> dict:
    """Return list of legendary record labels and unlimited deep catalog."""
    labels_list = [
        {
            "id": k,
            "name": v["name"],
            "city": v["city"],
            "founded": v["founded"],
            "vibe": v["vibe"],
            "icon": v["icon"],
            "color": v["color"],
            "count": len(v["albums"])
        }
        for k, v in RECORD_LABELS.items()
    ]
    key = str(label_key or "").strip()
    match_key = None
    for k in RECORD_LABELS:
        if k.lower() == key.lower() or key.lower() in k.lower():
            match_key = k
            break
    if not match_key:
        match_key = "Sub Pop"

    selected = RECORD_LABELS[match_key]
    curated = selected["albums"]
    label_search_name = selected.get("search_name") or selected["name"]

    if offset == 0:
        seen_ids = {str(a["id"]) for a in curated}
        live_needed = max(0, limit - len(curated))
        live_albums = _fetch_live_label_albums(label_search_name, limit=max(25, live_needed), offset=0)
        merged = list(curated)
        for la in live_albums:
            if str(la["id"]) not in seen_ids:
                seen_ids.add(str(la["id"]))
                merged.append(la)
        return {
            "active_label": match_key,
            "label_info": {
                "name": selected["name"],
                "city": selected["city"],
                "founded": selected["founded"],
                "vibe": selected["vibe"],
                "icon": selected["icon"],
                "color": selected["color"]
            },
            "labels": labels_list,
            "albums": merged,
            "total": len(merged),
            "offset": 0,
            "has_more": True
        }
    else:
        live_albums = _fetch_live_label_albums(label_search_name, limit=limit, offset=offset)
        curated_ids = {str(a["id"]) for a in curated}
        clean_live = [a for a in live_albums if str(a["id"]) not in curated_ids]
        return {
            "active_label": match_key,
            "label_info": {
                "name": selected["name"],
                "city": selected["city"],
                "founded": selected["founded"],
                "vibe": selected["vibe"],
                "icon": selected["icon"],
                "color": selected["color"]
            },
            "labels": labels_list,
            "albums": clean_live,
            "total": len(clean_live),
            "offset": offset,
            "has_more": len(live_albums) >= limit
        }


def get_landmark_album_details(aid: str) -> dict:
    """Resolve landmark or record label album to complete details structure."""
    clean_aid = str(aid or "").strip()
    match_alb = None
    for y, albs in TIMEMACHINE_LANDMARKS.items():
        for a in albs:
            if str(a["id"]) == clean_aid:
                match_alb = dict(a)
                break
        if match_alb:
            break

    if not match_alb:
        for lkey, lobj in RECORD_LABELS.items():
            for a in lobj["albums"]:
                if str(a["id"]) == clean_aid:
                    match_alb = dict(a)
                    break
            if match_alb:
                break

    if not match_alb:
        from . import deezer_api
        return deezer_api.get_album_details(clean_aid)

    # Hydrate real tracks via Deezer if Deezer ID
    if clean_aid.isdigit():
        try:
            from . import deezer_api
            dz = deezer_api.get_album_details(clean_aid)
            if dz and "tracks" in dz and dz["tracks"]:
                dz["historical_context"] = match_alb.get("desc") or ""
                dz["label"] = match_alb.get("label") or match_alb.get("genre") or ""
                return dz
        except Exception:
            pass

    return {
        "id": match_alb["id"],
        "title": match_alb["title"],
        "artist": match_alb["artist"],
        "year": match_alb.get("year", "2024"),
        "genre": match_alb.get("genre", "Alternative"),
        "cover": match_alb.get("cover", "/placeholder-cover.svg"),
        "tracks_count": match_alb.get("tracks_count", 10),
        "historical_context": match_alb.get("desc", ""),
        "label": match_alb.get("label", ""),
        "tracks": [
            {
                "id": f"{match_alb['id']}-tr1",
                "title": f"{match_alb['title']} (Full Stream)",
                "artist": match_alb["artist"],
                "album": match_alb["title"],
                "duration": 240,
                "preview_url": "",
                "track_num": 1,
                "disc_num": 1,
            }
        ]
    }
